<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import PageHeader from '@/components/PageHeader.vue'
import MemberSelect from '@/components/MemberSelect.vue'
import { featureApi } from '@/api'
import { useAppStore } from '@/stores/app'
import { useAuthStore } from '@/stores/auth'
import { requireTreeId } from '@/utils/backend'
import type { Suggestion } from '@/types'
const props=withDefaults(defineProps<{review?:boolean}>(),{review:false}),app=useAppStore(),auth=useAuthStore(),items=ref<Suggestion[]>([]),dialog=ref(false),commentDialog=ref(false),current=ref<Suggestion>(),form=reactive({targetType:'MEMBER',targetId:'' as number|'',field:'name',value:'',reason:''}),reviewForm=reactive({approve:true,comment:''}),loading=ref(false)
async function load(){if(!auth.isAdmin){items.value=[];return}loading.value=true;try{items.value=await featureApi.pendingSuggestions(requireTreeId(app.activeTreeId))}finally{loading.value=false}}
async function submit(){if(!form.targetId){ElMessage.warning('请选择目标成员');return}await featureApi.suggest(requireTreeId(app.activeTreeId),{targetType:form.targetType,targetId:Number(form.targetId)||undefined,payload:{[form.field]:form.value,reason:form.reason}});ElMessage.success('建议已提交');dialog.value=false;if(props.review)load()}
function openReview(item:Suggestion,approve:boolean){current.value=item;reviewForm.approve=approve;reviewForm.comment='';commentDialog.value=true}
async function doReview(){if(!current.value)return;await featureApi.review(requireTreeId(app.activeTreeId),current.value.id,reviewForm.approve,reviewForm.comment);ElMessage.success('审核完成');commentDialog.value=false;load()}
onMounted(load)
</script>
<template><PageHeader :title="review?'管理员审核':'修改建议'" :description="`当前后端仅提供待审列表；家谱 #${app.activeTreeId}`"><el-button v-if="!review&&auth.isAdmin" type="primary" @click="dialog=true">提交建议</el-button></PageHeader><section class="panel"><el-table v-loading="loading" :data="items" stripe><el-table-column prop="targetType" label="对象类型"/><el-table-column prop="targetId" label="对象 ID"/><el-table-column prop="payloadJson" label="建议内容" min-width="320" show-overflow-tooltip/><el-table-column prop="submitterId" label="提交人 ID"/><el-table-column prop="createdAt" label="提交时间"/><el-table-column label="状态"><template #default="{row}"><el-tag effect="plain">{{row.status}}</el-tag></template></el-table-column><el-table-column v-if="review" label="审核"><template #default="{row}"><el-button link type="success" @click="openReview(row,true)">通过</el-button><el-button link type="danger" @click="openReview(row,false)">驳回</el-button></template></el-table-column></el-table><el-empty v-if="!loading&&!items.length" description="暂无待审核建议"/></section><el-dialog v-model="dialog" title="提交资料修改建议" width="min(560px,94vw)"><el-form label-position="top"><el-form-item label="目标成员"><MemberSelect v-model="form.targetId" :tree-id="app.activeTreeId"/></el-form-item><el-form-item label="修改字段"><el-select v-model="form.field"><el-option value="name" label="姓名"/><el-option value="notes" label="备注"/></el-select></el-form-item><el-form-item label="建议内容"><el-input v-model="form.value"/></el-form-item><el-form-item label="依据"><el-input v-model="form.reason" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="submit">提交</el-button></template></el-dialog><el-dialog v-model="commentDialog" title="审核意见" width="440px"><el-input v-model="reviewForm.comment" type="textarea" :rows="4"/><template #footer><el-button @click="commentDialog=false">取消</el-button><el-button :type="reviewForm.approve?'success':'danger'" @click="doReview">确认{{reviewForm.approve?'通过':'驳回'}}</el-button></template></el-dialog></template>
